package br.com.onda;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class LyricTranslationTest {
 @Test public void currentVerseFirstRepeatedVersesOnlyTranslateOnce(){List<String> called=new ArrayList<>();Map<Integer,String> shown=new HashMap<>();boolean[] done={false};LyricTranslation job=new LyricTranslation(Arrays.asList("Hello","","World","Hello"),2,(text,cb)->{called.add(text);cb.success("T:"+text);},new LyricTranslation.Listener(){public void row(int i,String t){shown.put(i,t);}public void complete(){done[0]=true;}public void failure(Exception e){fail();}});job.start();assertEquals(Arrays.asList("World","Hello"),called);assertEquals("T:Hello",shown.get(0));assertEquals(shown.get(0),shown.get(3));assertFalse(shown.containsKey(1));assertTrue(done[0]);}
 @Test public void cancellationIgnoresLateResultsAndDoesNotStartNextVerse(){LyricTranslation.Result[] pending={null};int[] calls={0};LyricTranslation job=new LyricTranslation(Arrays.asList("First","Second"),0,(text,cb)->{calls[0]++;pending[0]=cb;},new LyricTranslation.Listener(){public void row(int i,String t){fail();}public void complete(){fail();}public void failure(Exception e){fail();}});job.start();job.cancel();pending[0].success("Primeiro");assertEquals(1,calls[0]);}
 @Test public void errorKeepsOriginalVersesAndEndsTheQueue(){List<String> original=new ArrayList<>(Arrays.asList("First","Second"));int[] failed={0},calls={0};LyricTranslation job=new LyricTranslation(original,0,(text,cb)->{calls[0]++;cb.failure(new Exception("offline"));},new LyricTranslation.Listener(){public void row(int i,String t){fail();}public void complete(){fail();}public void failure(Exception e){failed[0]++;}});job.start();assertEquals(1,failed[0]);assertEquals(1,calls[0]);assertEquals(Arrays.asList("First","Second"),original);}
}
